fn main() {
    // Un littéral : son type est &'static str
    let salutation: &str = "bonjour";

    // Passer d'un &str à une String possédée
    let possedee: String = salutation.to_string();
    // Autre écriture équivalente :
    let aussi: String = String::from("bonjour");

    // Passer d'une String à un &str : on emprunte la totalité
    let vue: &str = &possedee[..]; // `&possedee` seul fonctionne aussi

    println!("{salutation} / {possedee} / {aussi} / {vue}");
}

// On lit seulement, donc on prend un &str
fn longueur(texte: &str) -> usize {
    texte.len() // longueur en octets (bytes)
}

fn main() {
    let litteral = "abc";
    let possedee = String::from("abcdef");

    // Les deux appels fonctionnent avec la MÊME fonction
    println!("{}", longueur(litteral));   // 3
    println!("{}", longueur(&possedee));  // 6 : &String devient &str
}

fn main() {
    let nombres = [10, 20, 30, 40, 50];
    let milieu: &[i32] = &nombres[1..3]; // positions 1 et 2
    println!("{milieu:?}"); // affiche : [20, 30]

    let phrase = String::from("bonjour le monde");
    let mot: &str = &phrase[0..7]; // octets 0 à 6
    println!("{mot}"); // affiche : bonjour

    // Raccourcis d'intervalle
    let debut = &nombres[..2];  // [10, 20]
    let fin = &nombres[3..];    // [40, 50]
    println!("{debut:?} {fin:?}");
}

sections.solution:
On cherche l'indice du premier espace, puis on renvoie la slice `&texte[0..i]`. Si aucun espace n'est trouvé, on renvoie `&texte[..]`, c'est à dire toute la chaîne.

```rust
fn premier_mot(texte: &str) -> &str {
    let octets = texte.as_bytes();
    for (i, &octet) in octets.iter().enumerate() {
        if octet == b' ' {
            return &texte[0..i]; // slice jusqu'avant l'espace
        }
    }
    &texte[..] // aucun espace : on renvoie tout
}

fn main() {
    println!("{}", premier_mot("bonjour le monde")); // bonjour
    println!("{}", premier_mot("solo"));             // solo
}
```

La fonction ne fait qu'emprunter une portion de l'entrée : aucune allocation, aucune copie. Le type de retour `&str` emprunte la même mémoire que le paramètre.
